import {readFileSync,writeFileSync,existsSync} from 'node:fs';
const plan=JSON.parse(readFileSync(process.argv[2],'utf8'));
const result={schemaVersion:1,status:'RUNNING',cells:[]};
for(const cell of plan.cells){
 if(cell.report&&existsSync(cell.report))throw Error('Existing report '+cell.report);
 console.log('START '+cell.id+' '+new Date().toISOString());
 const started=performance.now();
 const child=Bun.spawn(cell.command,{cwd:cell.cwd,stdout:'pipe',stderr:'pipe'});
 const [exitCode,stdout,stderr]=await Promise.all([child.exited,new Response(child.stdout).text(),new Response(child.stderr).text()]);
 const guardLine=stderr.split('\n').find(x=>x.startsWith('HEAVY_GATE '));
 const guardian=guardLine?JSON.parse(guardLine.slice(11)):null;
 const passed=exitCode===0&&(!guardian||guardian.status==='PASS')&&(cell.expectedStdout===undefined||stdout===cell.expectedStdout);
 result.cells.push({...cell,exitCode,elapsedMs:performance.now()-started,stdout,stderr,guardian,passed});
 writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');
 console.log('FINISH '+cell.id+' '+(passed?'PASS':'FAIL')+' '+new Date().toISOString());
 if(!passed){result.status='FAILED_CELL_RETAINED';writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');process.exit(exitCode||1);}
}
result.status='ALL_CELLS_FINISHED';writeFileSync(plan.output,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({status:result.status,cells:result.cells.length,output:plan.output}));
